```bash
cd /home/vscode/nullness-benchmarks/wala-util && sed -i '255,257c\	    public ByteArrayOutputStream getCapture() {
	      if (capture == null) {
	        capture = new ByteArrayOutputStream();
	      }
	      return capture;
	    }' src/main/java/com/ibm/wala/util/processes/Launcher.java && ./gradlew compileJava -x test -q > new_build_output.log 2>&1 && grep -n "Launcher.java" new_build_output.log || tail -n 40 new_build_output.log
